-- Dungeon Master's Guide source-backed rules catalog.
-- Mechanical summaries are intentionally concise; the supplied sourcebook remains authoritative.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dmg-3.5','dungeon-masters-guide-3-5','Dungeon Master''s Guide','DMG',
        'Wizards of the Coast','dnd','3.5','D&D v.3.5 core Dungeon Master''s Guide, including the official errata appended to the supplied source PDF.',NULL,1,0,NULL);

WITH desired(slug,name,source_page,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,summary,tags,mechanics) AS (VALUES
  ('dmg-dm-final-arbiter','DM as Final Arbiter','6','adjudication','guidance',0,1,NULL,NULL,'The DM resolves rules questions at the table, should know where to find rules, and should avoid overturning published rules without a sound reason.','["dm","adjudication","authority"]','{}'),
  ('dmg-uncovered-situations','Adjudicating Uncovered Situations','6','adjudication','procedure',0,1,NULL,NULL,'When no explicit rule covers a situation, extrapolate from a similar rule; if a new house rule is created, use it consistently.','["adjudication","house-rules"]','{}'),
  ('dmg-best-friend','DM''s Best Friend','6','adjudication','rule',0,1,NULL,NULL,'For an improvised d20 circumstance not otherwise covered, favorable conditions commonly grant +2 and unfavorable conditions impose -2.','["adjudication","circumstance"]','{"favorable_modifier":2,"unfavorable_modifier":-2,"roll":"d20"}'),
  ('dmg-rule-source-precedence','Primary Source Precedence','320','adjudication','rule',0,1,NULL,NULL,'Official errata controls conflicts. Otherwise text takes precedence over conflicting table summaries, and the book primary for a topic controls conflicting secondary sources.','["errata","precedence","primary-source"]','{"primary_topics":{"phb":["gameplay","pc_races","base_classes"],"dmg":["magic_items","special_materials"],"mm":["monsters","templates","special_abilities"]}}'),
  ('dmg-keep-game-moving','Keep the Game Moving','6','running-game','guidance',0,1,NULL,NULL,'Keeping play moving and preserving engagement is more important than prolonged rulebook searches or extended rules debates.','["pacing","table-management"]','{}'),
  ('dmg-table-rules','Table Rules','11','running-game','guidance',0,1,NULL,NULL,'Establish expectations for absent players, dice conventions, book use, rules discussions, jokes, and off-topic discussion before problems arise.','["table","social"]','{}'),
  ('dmg-metagame-thinking','Discourage Metagame Thinking','11','running-game','guidance',0,1,NULL,NULL,'Characters should act from information and logic available within the game world rather than assumptions about the DM or game structure.','["roleplaying","metagame"]','{}'),
  ('dmg-game-balance','Game Balance','13','running-game','guidance',0,1,NULL,NULL,'Character options should remain broadly comparable and encounters should neither be trivial nor consistently overwhelming; temporary imbalance is usually better corrected by adjusting challenges than stripping earned abilities.','["balance","encounters"]','{}'),
  ('dmg-house-rules','Changing the Rules and House Rules','14','adjudication','guidance',0,1,NULL,NULL,'Before changing a rule, understand how it works, why it exists, its interactions, and whether the change disproportionately favors an option or harms enjoyment.','["house-rules","variants"]','{}'),
  ('dmg-grid-movement','Movement on the Battle Grid','19','movement','rule',0,1,NULL,NULL,'Combat movement uses squares and miniature positioning; out of combat, common-sense movement can override grid abstractions that would needlessly obstruct ordinary movement.','["grid","movement"]','{}'),
  ('dmg-three-dimensional-movement','Moving in Three Dimensions','20','movement','rule',0,1,NULL,NULL,'Flying and other three-dimensional movement uses maneuverability limits for forward speed, hovering, turns, ascent, descent, and changing vertical direction.','["flight","movement"]','{}'),
  ('dmg-flight-maneuverability','Flight Maneuverability','20','movement','table',0,1,NULL,NULL,'Perfect, good, average, poor, and clumsy maneuverability define minimum forward speed, turning, ascent/descent angles, and hover capability.','["flight","maneuverability"]','{}'),
  ('dmg-evasion-pursuit-short','Short Evasion and Pursuit','20','movement','procedure',0,1,NULL,NULL,'When pursuer and quarry have equal speed and a chase lasts several rounds, resolve the contest with opposed Dexterity checks; quarry wins to escape, pursuer wins to catch.','["chase","movement"]','{"check":"dexterity","opposed":true,"scope":"short_chase"}'),
  ('dmg-evasion-pursuit-long','Long Evasion and Pursuit','20','movement','procedure',0,1,NULL,NULL,'For an overland pursuit lasting much longer, opposed Constitution checks determine who can maintain the pace; the quarry escapes by winning, otherwise the pursuer runs it down.','["chase","movement"]','{"check":"constitution","opposed":true,"scope":"long_chase"}'),
  ('dmg-bonus-types-stacking','Bonus Types and Stacking','21','bonuses','rule',0,1,NULL,NULL,'Bonuses of different types generally stack. Bonuses of the same named type generally do not; apply only the better one unless the rules specifically say otherwise.','["bonuses","stacking"]','{"same_type_stacks":false,"different_types_stack":true}'),
  ('dmg-dodge-bonus-stacking','Dodge Bonuses Stack','21','bonuses','rule',0,1,NULL,NULL,'Dodge bonuses stack with one another unless a more specific rule says otherwise.','["bonuses","stacking"]','{"bonus_type":"dodge","stacks_with_same_type":true}'),
  ('dmg-circumstance-bonus-stacking','Circumstance Bonuses','21','bonuses','rule',0,1,NULL,NULL,'Circumstance bonuses can stack when they arise from different circumstances.','["bonuses","stacking"]','{"bonus_type":"circumstance","same_source_stacks":false,"different_source_stacks":true}'),
  ('dmg-inherent-bonus-limit','Inherent Bonus Limit','21','bonuses','rule',0,1,NULL,NULL,'An ability score cannot receive more than a +5 inherent bonus.','["bonuses","ability-scores"]','{"bonus_type":"inherent","max_per_ability":5}'),
  ('dmg-line-of-sight','Line of Sight','21','combat','rule',0,1,NULL,NULL,'A completely blocked line of sight prevents targeting with ranged attacks or spells that require sight. Partial blocking can provide cover rather than total denial.','["line-of-sight","cover"]','{}'),
  ('dmg-starting-encounter','Starting an Encounter','22','combat','procedure',0,1,NULL,NULL,'Determine awareness, surprise, positions, and initiative as appropriate when an encounter begins.','["initiative","surprise"]','{}'),
  ('dmg-new-combatants','New Combatants Entering Combat','23','combat','rule',0,1,NULL,NULL,'Creatures entering an ongoing encounter are inserted into the initiative sequence according to the encounter rules rather than restarting initiative.','["initiative"]','{}'),
  ('dmg-combat-actions-adjudication','Combat Action Adjudication','25','combat','guidance',0,1,NULL,NULL,'Use the defined action economy and adjudicate unusual attempts by comparison to existing actions and consequences.','["actions","combat"]','{}'),
  ('dmg-automatic-hits-misses','Automatic Hits and Misses','25','combat','rule',0,1,NULL,NULL,'Natural attack-roll extremes follow the core automatic-hit and automatic-miss rules even when modifiers would otherwise suggest a different result.','["attack-roll"]','{}'),
  ('dmg-weapon-size-damage','Weapon Size and Damage','28','combat','rule',0,1,NULL,NULL,'Weapon damage scales by weapon size using the weapon-size progression; creature size affects whether a weapon can be wielded and how.','["weapons","size"]','{}'),
  ('dmg-splash-weapons','Splash Weapons','28','combat','rule',0,1,NULL,NULL,'Thrown splash weapons use the splash-weapon targeting, miss-direction, and adjacent splash-damage procedure.','["weapons","splash"]','{}'),
  ('dmg-area-effects-grid','Area Effects on a Grid','28','combat','rule',0,1,NULL,NULL,'Areas such as bursts, cones, lines, and spreads occupy grid squares according to their geometric templates and origin rules.','["area","grid","spells"]','{}'),
  ('dmg-big-little-creatures','Big and Little Creatures in Combat','29','combat','rule',0,1,NULL,NULL,'Creature size changes occupied space, reach, squeezing, and how creatures interact on the grid.','["size","space","reach"]','{}'),
  ('dmg-skill-check-dc-adjudication','Skill and Ability Check DCs','30','checks','procedure',0,1,NULL,NULL,'Set DCs by comparing the task to established examples and difficulty bands; use opposed checks when success depends directly on another creature.','["skills","dc"]','{}'),
  ('dmg-saving-throws-adjudication','Saving Throw Adjudication','33','checks','rule',0,1,NULL,NULL,'Use Fortitude, Reflex, or Will according to the nature of the effect and apply the effect''s specified save result; a save normally represents a reactive defense rather than an action.','["saving-throws"]','{}'),
  ('dmg-divinations','Handling Divinations','34','magic','guidance',0,1,NULL,NULL,'Divination results should respect the spell''s limits and can be phrased in ways appropriate to the information source without negating the spell''s legitimate benefit.','["magic","divination"]','{}'),
  ('dmg-create-new-spells','Creating New Spells','35','magic','guidance',0,1,NULL,NULL,'New spells should be benchmarked against spells of similar level, role, duration, range, and impact; avoid making a new spell strictly superior to existing choices.','["spells","design"]','{}'),
  ('dmg-experience-awards','Experience Awards','36','rewards','procedure',0,1,NULL,NULL,'Award XP based on encounter Challenge Rating relative to each character''s level, then divide encounter awards among participating characters as directed by the XP system.','["xp","cr"]','{}'),
  ('dmg-challenge-rating-xp','Challenge Rating to XP','38','rewards','table',0,1,NULL,NULL,'The CR-to-character-level XP table gives the base XP earned by a character for overcoming a challenge of a given CR.','["xp","cr","table"]','{}'),
  ('dmg-story-awards','Story Awards','40','rewards','guidance',0,1,NULL,NULL,'Story goals and noncombat accomplishments can earn XP awards comparable to challenges of an appropriate difficulty.','["xp","story"]','{}'),
  ('dmg-noncombat-challenge-awards','Noncombat Challenge Awards','40','rewards','guidance',0,1,NULL,NULL,'A meaningful noncombat obstacle can be assigned a CR or equivalent award based on its difficulty and importance.','["xp","noncombat"]','{}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'dmg-3.5-rule-' || d.slug, 'dmg-3.5', d.source_page, d.slug, d.name, d.summary, d.summary,
  0,NULL,1,d.category,d.kind,d.is_variant,d.default_enabled,d.parent_slug,d.supersedes_slug,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r
  WHERE r.slug=d.slug AND r.owner_user_id IS NULL
);
